// @name Voice memos
// @background #f6f1e7
// @refresh 3600
// Voice memos: hold the frame's voice key and speak, and what you said is
// saved as a memo, a text file in the frame's assets folder, and listed here,
// newest first. The voice key stays the frame's AI key: what matches
// something on the screen is done ("open the plumber memo", "delete the
// last one", "next page"), and only what matches nothing becomes a memo:
// the scene's custom event `voiceMemo` is its `voice: fallback`, which the
// control plane sends with {text, at} (docs/voice-chat.md "Voice actions").
// Without a microphone (a Pi, the preview) type a memo at the bottom and
// Save. Tap a memo to read all of it, the bin to delete it (it asks first).
//
// Every memo is one file: <folder>/<YYYY-MM-DD HH.MM.SS>.txt in the frame's
// local time, UTF-8. Files are the memory: nothing else is kept, so a memo
// copied off the frame, or one dropped into the folder, is a memo here.

const MAX_CHARS = 8000 // a memo longer than this is cut (30 s of speech is far less)
const PREVIEW_BYTES = 240 // what is read of a memo for its row
const HINT = 'On a frame with a microphone, hold the voice key and speak.'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// Warm paper, navy ink, one terracotta accent for what was just saved and
// for Save. High contrast: black on white, borders instead of tints.
const THEMES = {
  color: {
    page: 'bg-[#f6f1e7] text-[#1d2b4a]',
    muted: 'text-[#5d6880]',
    card: 'bg-white border border-[#e4dccb]',
    fresh: 'bg-white border-2 border-[#c2553a]',
    when: 'text-[#1d2b4a]',
    accent: 'text-[#c2553a]',
    dot: 'bg-[#c2553a]',
    field: 'bg-white border border-[#d8cfbd] focus:border-[#1d2b4a]',
    save: 'bg-[#c2553a] text-white active:bg-[#a5452d]',
    plain: 'bg-[#e9e1d1] text-[#1d2b4a] active:bg-[#ddd3bf]',
    remove: 'bg-[#1d2b4a] text-white active:bg-[#2c3d63]',
    off: 'text-[#b9b2a3]',
    banner: 'bg-[#1d2b4a] text-white',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    card: 'bg-white border-2 border-black',
    fresh: 'bg-white border-4 border-black',
    when: 'text-black',
    accent: 'text-black',
    dot: 'bg-black',
    field: 'bg-white border-2 border-black',
    save: 'bg-black text-white',
    plain: 'bg-white text-black border-2 border-black',
    remove: 'bg-black text-white',
    off: 'text-white',
    banner: 'bg-black text-white',
  },
}

// ------------------------------------------------------------------ files

// The folder setting as a path in the assets folder: no leading or trailing
// slash, no "..", no hidden names (the frame refuses those anyway).
const folderOf = (app) => {
  const parts = String(app.state.folder ?? '')
    .split('/')
    .map((part) => part.trim())
    .filter((part) => part && part !== '.' && part !== '..' && !part.startsWith('.'))
  return parts.length ? parts.join('/') : 'Voice memos'
}

// makeAssetFolder makes one folder inside one that is there: walk down.
const ensureFolder = (folder) => {
  let path = ''
  for (const part of folder.split('/')) {
    path = path ? `${path}/${part}` : part
    if (!frameos.assetExists(path)) frameos.makeAssetFolder(path)
  }
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

// writeAsset takes base64, and the runtime has no btoa or TextEncoder: the
// text's UTF-8 bytes, then base64, by hand.
const utf8Base64 = (text) => {
  const bytes = []
  for (let i = 0; i < text.length; i++) {
    let c = text.charCodeAt(i)
    if (c >= 0xd800 && c < 0xdc00 && i + 1 < text.length) {
      const low = text.charCodeAt(i + 1)
      if (low >= 0xdc00 && low < 0xe000) {
        c = 0x10000 + ((c - 0xd800) << 10) + (low - 0xdc00)
        i++
      }
    }
    if (c >= 0xd800 && c < 0xe000) c = 0xfffd // half a pair: the replacement character
    if (c < 0x80) bytes.push(c)
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63))
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63))
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63))
  }
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0)
    out += B64[(n >> 18) & 63] + B64[(n >> 12) & 63]
    out += i + 1 < bytes.length ? B64[(n >> 6) & 63] : '='
    out += i + 2 < bytes.length ? B64[n & 63] : '='
  }
  return out
}

const pad = (n, width = 2) => String(n).padStart(width, '0')

// "2026-11-18 11.04.05" in the frame's local time (Date is local on a frame).
const stamp = (date) =>
  `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ` +
  `${pad(date.getHours())}.${pad(date.getMinutes())}.${pad(date.getSeconds())}`

// The text as it is kept: no control characters but line breaks, trimmed, cut.
const cleanText = (raw) =>
  String(raw ?? '')
    .replace(/\r\n?/g, '\n')
    .replace(/[\u0000-\u0009\u000b-\u001f\u007f]/g, ' ')
    .trim()
    .slice(0, MAX_CHARS)

// Save one memo; the path, or null when it was empty or the frame refused it.
const saveMemo = (app, raw, at) => {
  const text = cleanText(raw)
  if (!text) return null
  const parsed = at ? new Date(at) : null
  const when = parsed && !isNaN(parsed.getTime()) ? parsed : new Date()
  const folder = folderOf(app)
  ensureFolder(folder)
  // Two memos in one second: "… 2.txt", "… 3.txt".
  const base = `${folder}/${stamp(when)}`
  let path = `${base}.txt`
  for (let n = 2; frameos.assetExists(path) && n < 100; n++) path = `${base} ${n}.txt`
  if (!frameos.writeAsset(path, utf8Base64(`${text}\n`))) {
    frameos.remember('error', 'The memo could not be saved: the frame refused the file.')
    frameos.log(`Voice memos: could not write ${path}`)
    return null
  }
  frameos.remember('error', null)
  frameos.remember('fresh', path)
  frameos.remember('open', null)
  frameos.remember('asking', null)
  // The list turns to the page that holds it (get() finds it).
  frameos.remember('seek', path)
  return path
}

const NAME = /^(\d{4})-(\d\d)-(\d\d) (\d\d)\.(\d\d)\.(\d\d)(?: (\d+))?\.txt$/i

// The folder's memos, sorted: {path, name, date (or null for a file not
// named by this scene)}. Only the names are read here.
const listMemos = (app) => {
  const folder = folderOf(app)
  const memos = []
  for (const path of frameos.listAssets(folder, { shallow: true }) || []) {
    if (path.endsWith('/') || !/\.txt$/i.test(path)) continue
    const name = path.slice(path.lastIndexOf('/') + 1)
    const m = NAME.exec(name)
    const date = m ? new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]) : null
    // "… 05 2.txt" sorts after "… 05.txt" (a space sorts before a dot).
    const key = m ? `${m[1]}${m[2]}${m[3]}${m[4]}${m[5]}${m[6]}${pad(m[7] ? +m[7] : 1, 3)}` : `0 ${name}`
    memos.push({ path, name, date, key })
  }
  memos.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0))
  if (app.state.sort !== 'oldest') memos.reverse()
  return memos
}

// A memo's first words for its row. Files do not change once written, so
// the preview is remembered per path (only the page's, to stay small).
const previewsFor = (memos) => {
  const kept = frameos.recall('previews') || {}
  const next = {}
  let read = false
  for (const memo of memos) {
    if (typeof kept[memo.path] === 'string') {
      next[memo.path] = kept[memo.path]
      continue
    }
    const text = frameos.readAsset(memo.path, { text: true, length: PREVIEW_BYTES })
    next[memo.path] = (text || '').replace(/\s+/g, ' ').trim()
    read = true
  }
  if (read || Object.keys(kept).length !== memos.length) frameos.remember('previews', next)
  return next
}

// ------------------------------------------------------------------- time

const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

const clock = (app, date) => {
  if (app.state.timeFormat === '12h') {
    const h = date.getHours() % 12 || 12
    return `${h}:${pad(date.getMinutes())} ${date.getHours() < 12 ? 'AM' : 'PM'}`
  }
  return `${pad(date.getHours())}:${pad(date.getMinutes())}`
}

// "Today", "Yesterday", "Wed 18 Nov", or "18 Nov 2025" for another year.
const dayLabel = (date, now) => {
  const startOf = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
  const days = Math.round((startOf(now) - startOf(date)) / 86400000)
  if (days === 0) return 'Today'
  if (days === 1) return 'Yesterday'
  const short = `${date.getDate()} ${MONTHS[date.getMonth()].slice(0, 3)}`
  if (date.getFullYear() !== now.getFullYear()) return `${short} ${date.getFullYear()}`
  return `${DAYS[date.getDay()].slice(0, 3)} ${short}`
}

const longDate = (app, date) =>
  `${DAYS[date.getDay()]} ${date.getDate()} ${MONTHS[date.getMonth()]} ${date.getFullYear()}, ${clock(app, date)}`

// ----------------------------------------------------------------- events

// The plane sends {text, at} when the voice key was held over this scene;
// back and forward turn the pages, or close and step through an open memo.
export function onEvent(app, context) {
  if (context.event === 'voiceMemo') {
    const payload = context.payload || {}
    if (!cleanText(payload.text)) return false // nothing heard: nothing to save or draw
    saveMemo(app, payload.text, payload.at) // a refused write shows its banner
    return true
  }
  const open = frameos.recall('open')
  if (open) {
    if (context.event === 'back') {
      frameos.remember('open', null)
      return true
    }
    if (context.event === 'forward') {
      const memos = listMemos(app)
      const at = memos.findIndex((memo) => memo.path === open)
      if (at >= 0 && at + 1 < memos.length) {
        frameos.remember('open', memos[at + 1].path)
        return true
      }
    }
    return false
  }
  const page = frameos.recall('page') || 0
  if (context.event === 'back' && page > 0) {
    frameos.remember('page', page - 1)
    return true
  }
  if (context.event === 'forward') {
    frameos.remember('page', page + 1) // get() holds it to the last page
    return true
  }
  return false
}

// ------------------------------------------------------------------ icons

const Icon = ({ d, size, className = '' }) => (
  <svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="currentColor">
    <path d={d} />
  </svg>
)
const MIC =
  'M12,2A3,3 0 0,1 15,5V11A3,3 0 0,1 12,14A3,3 0 0,1 9,11V5A3,3 0 0,1 12,2M19,11C19,14.53 16.39,17.44 13,17.93V21H11V17.93C7.61,17.44 5,14.53 5,11H7A5,5 0 0,0 12,16A5,5 0 0,0 17,11H19Z'
const BIN = 'M9,3V4H4V6H5V19A2,2 0 0,0 7,21H17A2,2 0 0,0 19,19V6H20V4H15V3H9M7,6H17V19H7V6M9,8V17H11V8H9M13,8V17H15V8H13Z'
const LEFT = 'M15.41,16.58L10.83,12L15.41,7.41L14,6L8,12L14,18L15.41,16.58Z'
const RIGHT = 'M8.59,16.58L13.17,12L8.59,7.41L10,6L16,12L10,18L8.59,16.58Z'

// --------------------------------------------------------------------- UI

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const t = highContrast(app) ? THEMES.high : THEMES.color
  // One unit per 480 px of the shorter side, so 800x480, 480x800 and 480x480
  // read the same and a 1600x1200 panel is drawn larger.
  const s = Math.max(0.8, Math.min(2, Math.min(W, H) / 480))
  const px = (n) => Math.round(n * s)
  const portrait = H > W * 1.1
  const narrow = W < 640 // a square or small panel: no count in the header
  const now = new Date()
  const title = String(app.state.title ?? '').trim() || 'Voice memos'
  const error = frameos.recall('error')

  const memos = listMemos(app)
  const openPath = frameos.recall('open')
  const open = openPath ? memos.find((memo) => memo.path === openPath) : null
  const asking = frameos.recall('asking')
  const fresh = frameos.recall('fresh')

  const pad4 = px(16)
  const remove = (path) => {
    frameos.deleteAsset(path)
    frameos.remember('asking', null)
    frameos.remember('open', null)
    if (fresh === path) frameos.remember('fresh', null)
  }
  // "today, 11:04" inside a sentence
  const whenOf = (memo) =>
    memo.date
      ? `${dayLabel(memo.date, now).replace(/^(Today|Yesterday)/, (word) => word.toLowerCase())}, ${clock(app, memo.date)}`
      : memo.name.replace(/\.txt$/i, '')

  const banner = error ? (
    <div className={`flex items-center gap-3 rounded-xl px-4 py-2 ${t.banner}`} onClick={() => frameos.remember('error', null)}>
      <span className={`flex-1 text-[${px(16)}px]`}>{error}</span>
      <span className={`text-[${px(16)}px] font-bold`}>OK</span>
    </div>
  ) : null

  // ---- one memo, all of it
  if (open) {
    const text = (frameos.readAsset(open.path, { text: true }) || '').trim()
    const paragraphs = text.split(/\n+/)
    const confirming = asking === open.path
    // The text scrolls in a box of a known height (a scroller needs one):
    // the canvas less the margins, the button row, the card's padding and date.
    const bodyH = H - 2 * pad4 - px(48) - px(12) - 2 * px(20) - px(22) - px(12) - (error ? px(56) : 0)
    return (
      <div className={`flex flex-col w-full h-full gap-[${px(12)}px] p-[${pad4}px] ${t.page}`}>
        <div className="flex items-center gap-3">
          <div className={`h-[${px(48)}px] pl-2 pr-4 rounded-xl flex items-center text-[${px(18)}px] font-bold ${t.plain}`}
            onClick={() => { frameos.remember('open', null); frameos.remember('asking', null) }}>
            <Icon d={LEFT} size={px(28)} />
            <span>{portrait ? 'Back' : title}</span>
          </div>
          <div className="flex-1" />
          {confirming ? (
            <div className="flex items-center gap-2">
              <span className={`text-[${px(18)}px] font-bold`}>Delete it?</span>
              <div className={`h-[${px(48)}px] px-4 rounded-xl flex items-center text-[${px(18)}px] ${t.plain}`}
                onClick={() => frameos.remember('asking', null)}>Cancel</div>
              <div className={`h-[${px(48)}px] px-4 rounded-xl flex items-center text-[${px(18)}px] font-bold ${t.remove}`}
                onClick={() => remove(open.path)}>Delete</div>
            </div>
          ) : (
            <div className={`h-[${px(48)}px] px-4 rounded-xl flex items-center gap-1 text-[${px(18)}px] ${t.plain}`}
              onClick={() => frameos.remember('asking', open.path)}>
              <Icon d={BIN} size={px(24)} />
              <span>Delete</span>
            </div>
          )}
        </div>
        {banner}
        <div className={`flex flex-col flex-1 rounded-2xl p-[${px(20)}px] gap-[${px(12)}px] ${t.card}`}>
          <span className={`h-[${px(22)}px] text-[${px(16)}px] font-bold ${t.accent}`}>
            {open.date ? longDate(app, open.date) : open.name}
          </span>
          <div className={`h-[${bodyH}px] overflow-y-auto`}>
            <div className={`flex flex-col gap-[${px(12)}px]`}>
              {paragraphs.map((line) => (
                <span className={`text-[${px(24)}px] leading-snug`}>{line}</span>
              ))}
            </div>
          </div>
        </div>
      </div>
    )
  }

  // ---- the list, a page at a time (a row per memo, only the page is read)
  const headerH = px(portrait ? 92 : 80) // room for the hint on two lines
  const composerH = px(56)
  const rowH = px(portrait ? 84 : 64)
  const gap = px(8)
  const room = H - 2 * pad4 - headerH - composerH - 2 * px(12) - (error ? px(44) : 0)
  const perPage = Math.max(1, Math.floor((room + gap) / (rowH + gap)))
  const pages = Math.max(1, Math.ceil(memos.length / perPage))
  let page = Math.min(Math.max(0, frameos.recall('page') || 0), pages - 1)
  const seek = frameos.recall('seek')
  if (seek) {
    const at = memos.findIndex((memo) => memo.path === seek)
    if (at >= 0) page = Math.floor(at / perPage)
    frameos.remember('page', page)
    frameos.remember('seek', null)
  }
  const shown = memos.slice(page * perPage, (page + 1) * perPage)
  const previews = previewsFor(shown)
  const turn = (to) => {
    frameos.remember('page', to)
    frameos.remember('asking', null)
  }

  const draft = frameos.recall('draft') || ''
  const save = () => {
    if (saveMemo(app, frameos.recall('draft') || '', null)) frameos.remember('draft', '')
  }

  const pager =
    pages > 1 ? (
      <div className="flex items-center gap-1">
        <div className={`w-[${px(48)}px] h-[${px(48)}px] rounded-xl flex items-center justify-center ${page > 0 ? t.plain : ''}`}
          title="Previous page" onClick={() => { if (page > 0) turn(page - 1) }}>
          <Icon d={LEFT} size={px(30)} className={page > 0 ? '' : t.off} />
        </div>
        <span className={`text-[${px(16)}px] ${t.muted}`}>{`${page + 1} / ${pages}`}</span>
        <div className={`w-[${px(48)}px] h-[${px(48)}px] rounded-xl flex items-center justify-center ${page + 1 < pages ? t.plain : ''}`}
          title="Next page" onClick={() => { if (page + 1 < pages) turn(page + 1) }}>
          <Icon d={RIGHT} size={px(30)} className={page + 1 < pages ? '' : t.off} />
        </div>
      </div>
    ) : null

  const count = memos.length === 1 ? '1 memo' : `${memos.length} memos`

  const row = (memo) => {
    const preview = previews[memo.path] || ''
    if (asking === memo.path) {
      return (
        <div className={`flex items-center gap-3 rounded-2xl px-4 h-[${rowH}px] ${t.card}`}>
          <span className={`flex-1 text-[${px(18)}px] truncate`}>{`Delete the memo from ${whenOf(memo)}?`}</span>
          <div className={`h-[${px(46)}px] px-4 rounded-xl flex items-center text-[${px(18)}px] ${t.plain}`}
            onClick={() => frameos.remember('asking', null)}>Cancel</div>
          <div className={`h-[${px(46)}px] px-4 rounded-xl flex items-center text-[${px(18)}px] font-bold ${t.remove}`}
            onClick={() => remove(memo.path)}>Delete</div>
        </div>
      )
    }
    const isFresh = memo.path === fresh
    const when = memo.date ? (
      <div className={portrait ? 'flex items-center gap-2' : `flex flex-col w-[${px(132)}px] shrink-0`}>
        <span className={`text-[${px(15)}px] ${isFresh ? `font-bold ${t.accent}` : t.muted}`}>
          {isFresh ? 'Just saved' : dayLabel(memo.date, now)}
        </span>
        <span className={`text-[${px(portrait ? 15 : 22)}px] font-bold ${t.when}`}>{clock(app, memo.date)}</span>
      </div>
    ) : (
      <span className={`text-[${px(15)}px] ${t.muted} truncate ${portrait ? '' : `w-[${px(132)}px] shrink-0`}`}>{memo.name}</span>
    )
    return (
      <div className={`flex items-center gap-2 rounded-2xl pl-4 pr-1 h-[${rowH}px] ${isFresh ? t.fresh : t.card}`}>
        <div className={`flex-1 min-w-0 h-full gap-[${px(portrait ? 2 : 14)}px] ${portrait ? 'flex flex-col justify-center' : 'flex items-center'}`}
          onClick={() => { frameos.remember('open', memo.path); frameos.remember('asking', null); frameos.remember('fresh', null) }}>
          {when}
          <span className={`flex-1 min-w-0 text-[${px(19)}px] ${portrait ? 'line-clamp-2 leading-snug' : 'line-clamp-2 leading-snug'}`}>
            {preview || '(empty)'}
          </span>
        </div>
        <div className={`w-[${px(48)}px] h-[${px(48)}px] shrink-0 rounded-xl flex items-center justify-center ${t.muted}`}
          title="Delete" onClick={() => frameos.remember('asking', memo.path)}>
          <Icon d={BIN} size={px(24)} />
        </div>
      </div>
    )
  }

  const empty = (
    <div className="flex flex-col flex-1 items-center justify-center gap-3">
      <div className={`w-[${px(84)}px] h-[${px(84)}px] rounded-full flex items-center justify-center ${t.card}`}>
        <Icon d={MIC} size={px(46)} className={t.accent} />
      </div>
      <span className={`text-[${px(24)}px] font-bold`}>No memos yet</span>
      <span className={`text-[${px(17)}px] ${t.muted} text-center px-4`}>{`${HINT} Or type one below.`}</span>
    </div>
  )

  return (
    <div className={`flex flex-col w-full h-full gap-[${px(12)}px] p-[${pad4}px] ${t.page}`}>
      <div className={`flex items-center gap-3 h-[${headerH}px]`}>
        <div className={`w-[${px(52)}px] h-[${px(52)}px] shrink-0 rounded-full flex items-center justify-center ${t.dot}`}>
          <Icon d={MIC} size={px(30)} className="text-white" />
        </div>
        <div className="flex flex-col flex-1 min-w-0">
          <span className={`text-[${px(30)}px] font-bold truncate`}>{title}</span>
          <span className={`text-[${px(15)}px] ${t.muted} line-clamp-2`}>{HINT}</span>
        </div>
        {memos.length && !narrow && !(portrait && pager) ? <span className={`text-[${px(16)}px] ${t.muted} shrink-0`}>{count}</span> : null}
        {pager}
      </div>
      {banner}
      {memos.length ? (
        <div className={`flex flex-col flex-1 gap-[${gap}px]`}>{shown.map(row)}</div>
      ) : (
        empty
      )}
      <div className={`flex items-center gap-3 h-[${composerH}px]`}>
        <input className={`flex-1 h-full px-4 rounded-xl text-[${px(19)}px] ${t.field}`}
          value={draft} placeholder="Type a memo"
          onChange={(e) => frameos.remember('draft', e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter') save() }} />
        <div className={`h-full px-[${px(22)}px] rounded-xl flex items-center text-[${px(19)}px] font-bold ${draft.trim() ? t.save : t.plain}`}
          onClick={save}>
          Save
        </div>
      </div>
    </div>
  )
}
